/**
 * Builds the conformance suite.
 *
 * A specification with one implementation is a description of that
 * implementation. This produces containers with verdicts stated ahead of time,
 * so a second implementation can be checked against the format rather than
 * against our source code — and so ours can be checked against the format too.
 *
 * The expected verdicts here are written by hand from the specification, not
 * recorded from what this reader happens to do. The script then runs our reader
 * over every case and refuses to write the suite if the two disagree. A suite
 * generated by recording our own output would agree with us by construction and
 * prove nothing.
 *
 * Cases carry no SQLite engine. It contributes half a megabyte per file and
 * nothing to any of these checks, and a suite too large to keep in a repository
 * is a suite nobody runs.
 *
 * Run: node scripts/build-conformance.mjs
 */
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { unzipSync, zipSync } from "fflate";
import { buildContainer, toSectionedContainer } from "../dist/index.js";
import { auditContainer, parseContainer, verifyContainer } from "../dist/index.js";
import { SECTION, readContainerFile } from "../dist/index.js";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const dist = join(repo, "dist");
const suite = join(repo, "conformance");
const cases = join(suite, "cases");

const TEMPLATE = readFileSync(join(dist, "template.html"), "utf8");
const RUNTIME = readFileSync(join(dist, "dai-runtime.js"), "utf8");

const encoder = new TextEncoder();
const bytes = (text) => encoder.encode(text);

/** A fixed clock and a fixed identity, so a rebuild differs only where it must. */
const NOW = () => new Date("2026-01-01T00:00:00.000Z");
const UUID = "3f2504e0-4f89-41d3-9a0c-0305e82c3301";

/**
 * The signing key the suite is built with.
 *
 * Committed alongside the cases, and worthless: it signs documents that exist
 * to be checked. A key that could not be published would make the suite
 * unrebuildable by anyone else, which is the opposite of what it is for.
 */
const KEY = readFileSync(join(suite, "signing-key.pem"), "utf8");

const app = {
  "index.html": bytes(
    "<!doctype html><meta charset=utf-8><title>Conformance</title><p>A container that exists to be checked.</p>",
  ),
  "app.js": bytes("export const version = 1;\n"),
};

const base = (overrides = {}) => ({
  files: app,
  template: TEMPLATE,
  runtime: RUNTIME,
  appName: "Conformance",
  documentUuid: UUID,
  now: NOW,
  ...overrides,
});

/* The payload tag, matched the way the reader matches it rather than by a
   literal string: the attribute order is the template's business. */
const PAYLOAD_RE = /(<script[^>]*id="dai-payload"[^>]*>)([\s\S]*?)(<\/script>)/;

const archiveOf = (html) => unzipSync(Buffer.from(html.match(PAYLOAD_RE)[2], "base64"));

const repack = (html, archive) =>
  html.replace(
    PAYLOAD_RE,
    (_, open, __, close) =>
      open + Buffer.from(zipSync(archive, { level: 9 })).toString("base64") + close,
  );

/**
 * Every case: what the file is, and what any implementation must conclude.
 *
 * `mount` is the only answer that matters operationally — whether a host may
 * run this. The report fields say why, so an implementation that refuses for
 * the wrong reason does not pass by accident.
 */
const definitions = [];

const define = (name, summary, expect, make) =>
  definitions.push({ name, summary, expect, make });

define(
  "valid-unsigned",
  "A container as the compiler emits it, carrying no publisher key.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
  },
  async () => ({ file: "valid-unsigned.dai.html", body: (await buildContainer(base())).html }),
);

define(
  "valid-signed",
  "Signed with the suite's key. The signature covers the manifest, not the database.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "valid",
    expiry: "none",
  },
  async () => ({
    file: "valid-signed.dai.html",
    body: (await buildContainer(base({ signingKey: KEY }))).html,
  }),
);

define(
  "valid-signed-named",
  "Signed under a publisher name. The name is in the signed set, so it verifies with the rest.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "valid",
    expiry: "none",
  },
  async () => ({
    file: "valid-signed-named.dai.html",
    body: (await buildContainer(base({ signingKey: KEY, publisherName: "Acme Finance" }))).html,
  }),
);

define(
  "signed-name-changed",
  "The publisher name edited after signing. A name is a claim the key made, and another name is another claim.",
  {
    mount: false,
    ok: false,
    signature: "invalid",
    code: "UNVERIFIED_SIGNATURE",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY, publisherName: "Acme Finance" }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // Every entry still matches its digest and the signed set is untouched;
    // only the name has changed. A verifier that left the name out of the
    // signed view would accept "Acme Bank" on Acme Finance's signature.
    manifest.publisherName = "Acme Bank";
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-name-changed.dai.html", body: repack(html, archive) };
  },
);

define(
  "valid-signed-supersedes",
  "Signed, and naming the document it replaces. The name is in the signed set, so it cannot be pointed elsewhere.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "valid",
    expiry: "none",
  },
  async () => ({
    file: "valid-signed-supersedes.dai.html",
    body: (
      await buildContainer(base({ signingKey: KEY, supersedes: "11111111-2222-4333-8444-555555555555" }))
    ).html,
  }),
);

define(
  "valid-expiry-current",
  "Carries an expiry that has not passed. Accepted, and the expiry is reported.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "current",
  },
  async () => ({
    file: "valid-expiry-current.dai.html",
    // Far enough out that the suite does not expire before the format does.
    body: (await buildContainer(base({ validUntil: 4102444800 }))).html,
  }),
);

define(
  "expired",
  "The expiry has passed. A host must refuse rather than warn.",
  {
    mount: false,
    code: "KEY_EXPIRED",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "expired",
  },
  async () => ({
    file: "expired.dai.html",
    body: (await buildContainer(base({ validUntil: 1000000000 }))).html,
  }),
);

define(
  "entry-modified",
  "One application file has been edited. Its digest no longer matches the manifest.",
  {
    mount: false,
    code: "DIGEST_MISMATCH",
    ok: false,
    entries: { mismatched: ["app/app.js"], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base());
    const archive = archiveOf(html);
    archive["app/app.js"] = bytes("export const version = 2; // edited after signing\n");
    return { file: "entry-modified.dai.html", body: repack(html, archive) };
  },
);

define(
  "entry-added",
  "A file the manifest does not list. Refused: otherwise content can simply be appended.",
  {
    mount: false,
    code: "DIGEST_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: ["app/extra.js"] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base());
    const archive = archiveOf(html);
    archive["app/extra.js"] = bytes("console.log('not in the manifest');\n");
    return { file: "entry-added.dai.html", body: repack(html, archive) };
  },
);

define(
  "entry-removed",
  "The manifest lists a file the archive no longer carries.",
  {
    mount: false,
    code: "DIGEST_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: ["app/app.js"], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base());
    const archive = archiveOf(html);
    delete archive["app/app.js"];
    return { file: "entry-removed.dai.html", body: repack(html, archive) };
  },
);

define(
  "shell-modified",
  "The outer document differs from the sealed copy inside the payload.",
  {
    mount: false,
    code: "SHELL_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "mismatch",
    signature: "unsigned",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base());
    // A comment, and nothing else: the shell is compared byte for byte because
    // an edit that looks harmless is exactly how a bootloader gets replaced.
    return {
      file: "shell-modified.dai.html",
      body: html.replace("<head>", "<head><!-- added after sealing -->"),
    };
  },
);

define(
  "signature-invalid",
  "Signed, then the signature bytes were altered. The manifest is otherwise intact.",
  {
    mount: false,
    code: "UNVERIFIED_SIGNATURE",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    const raw = Buffer.from(manifest.signature, "base64");
    raw[raw.length - 1] ^= 0xff;
    manifest.signature = raw.toString("base64");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signature-invalid.dai.html", body: repack(html, archive) };
  },
);

define(
  "signed-entries-disagree",
  "The signed digest list disagrees with the digest list that was checked.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // The entry still hashes to what `hashes` claims, so every file checks out;
    // only the list the signature covers has been changed. An implementation
    // that verifies the signature without reconciling the two lists accepts a
    // signature over digests other than the ones it just checked.
    manifest.signedEntries["app/app.js"] = "0".repeat(64);
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-entries-disagree.dai.html", body: repack(html, archive) };
  },
);

define(
  "signed-extra-entry",
  "An entry added alongside a matching digest, with the signed list untouched.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // Every file checks out, including the new one: it is listed in `hashes`
    // with its true digest. Only `signedEntries` and the signature are as
    // they were. A reader that reconciles the signed list against `hashes`
    // in one direction only accepts this as authentic.
    const evil = bytes("console.log('not signed')");
    archive["app/evil.js"] = evil;
    manifest.hashes["app/evil.js"] = createHash("sha256").update(evil).digest("hex");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-extra-entry.dai.html", body: repack(html, archive) };
  },
);

define(
  "signed-schema-injected",
  "A schema declaration added the same way. A host runs its migration SQL.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // The same trick, aimed at the one unsigned entry a host executes:
    // migration SQL from a schema the publisher never declared, run against
    // the person's data under the publisher's badge.
    const schema = bytes(
      JSON.stringify({
        version: 2,
        tables: {},
        migrations: [{ version: 2, from: 1, to: 2, sql: "DROP TABLE IF EXISTS notes" }],
      }),
    );
    archive["runtime/schema.json"] = schema;
    manifest.hashes["runtime/schema.json"] = createHash("sha256").update(schema).digest("hex");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-schema-injected.dai.html", body: repack(html, archive) };
  },
);

define(
  "sectioned-valid",
  "The sectioned binary form, unmodified.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [], staleFooter: false },
  },
  async () => ({
    file: "sectioned-valid.dai",
    body: await toSectionedContainer(await buildContainer(base())),
  }),
);

define(
  "sectioned-payload-modified",
  "A byte inside the payload section no longer matches the section table.",
  {
    mount: false,
    code: "SECTION_MISMATCH",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [2], missing: [], staleFooter: false },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // Located from the table rather than guessed. The first attempt at this
    // case flipped a byte at a fixed offset, which landed in the manifest and
    // produced a case whose name said one thing and whose contents said
    // another — caught here only because the expectation was written first.
    const { offset } = readContainerFile(file).sections.find(
      (section) => section.id === SECTION.PAYLOAD,
    );
    file[offset + 16] ^= 0xff;
    return { file: "sectioned-payload-modified.dai", body: file };
  },
);

define(
  "sectioned-stale-footer",
  "The footer records a database other than the one the file carries.",
  {
    mount: false,
    code: "DATA_DAMAGED",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [], staleFooter: true },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // The last four bytes are the footer magic; the digest sits at +8.
    file[file.length - 64 + 8] ^= 0xff;
    return { file: "sectioned-stale-footer.dai", body: file };
  },
);

define(
  "sectioned-missing-data",
  "The section table declares no database. Not an empty document: an incomplete file.",
  {
    mount: false,
    code: "SECTION_MISSING",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [3], staleFooter: false },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // Two sections instead of three: the entry stays in the file, and the count
    // stops anything from reading it.
    new DataView(file.buffer, file.byteOffset).setUint32(8, 2, true);
    return { file: "sectioned-missing-data.dai", body: file };
  },
);

define(
  "not-a-container",
  "An HTML document that is not a container at all. Refused before any check runs.",
  { mount: false, parses: false },
  async () => ({
    file: "not-a-container.html",
    body: "<!doctype html><title>Ordinary page</title><p>No payload here.</p>",
  }),
);

/** What our own reader concludes, reduced to the shape the suite states. */
async function observe(body) {
  const source = typeof body === "string" ? body : new Uint8Array(body);
  const parsed = parseContainer(source);
  const report = await auditContainer(parsed);

  // Whether a host may run this, taken from the function a host actually calls
  // rather than inferred from the report. The two are meant to agree, and a
  // suite that assumed they did could not notice the day they stopped.
  let mount = true;
  let code;
  try {
    await verifyContainer(source);
  } catch (error) {
    mount = false;
    code = error && error.code;
  }

  const named = (status) =>
    report.entries.filter((entry) => entry.status === status).map((entry) => entry.name).sort();

  const observed = {
    mount,
    ok: report.ok,
    entries: {
      mismatched: named("mismatch"),
      missing: named("missing"),
      unlisted: named("unlisted"),
    },
    shell: report.shell.status,
    signature: report.signature.status,
    expiry: report.expiry.status,
  };
  if (code) observed.code = code;

  if (report.sections) {
    observed.sections = {
      mismatched: report.sections.mismatched,
      missing: report.sections.missing,
      staleFooter: report.sections.staleFooter,
    };
  }

  return observed;
}

const disagreements = [];

rmSync(cases, { recursive: true, force: true });
mkdirSync(cases, { recursive: true });

const written = [];

for (const definition of definitions) {
  const { file, body } = await definition.make();
  writeFileSync(join(cases, file), typeof body === "string" ? body : Buffer.from(body));

  if (definition.expect.parses === false) {
    let parsed = true;
    try {
      parseContainer(body);
    } catch {
      parsed = false;
    }
    if (parsed) disagreements.push(`${definition.name}: expected this not to parse, and it did.`);
  } else {
    const observed = await observe(body);
    for (const [key, value] of Object.entries(definition.expect)) {
      const seen = JSON.stringify(observed[key]);
      const stated = JSON.stringify(value);
      if (seen !== stated) {
        disagreements.push(`${definition.name}: expected ${key} ${stated}, this reader said ${seen}.`);
      }
    }
  }

  written.push({
    name: definition.name,
    file: `cases/${file}`,
    form: file.endsWith(".dai") ? "sectioned" : "viewer",
    summary: definition.summary,
    expect: definition.expect,
  });
}

if (disagreements.length > 0) {
  // Not written. A suite whose expectations were quietly adjusted to match this
  // reader is a record of this reader, and the point is to have something that
  // can tell us we are wrong.
  console.error("This implementation disagrees with the stated expectations:\n");
  for (const line of disagreements) console.error(`  ${line}`);
  process.exit(1);
}

writeFileSync(
  join(suite, "cases.json"),
  JSON.stringify(
    {
      suiteVersion: 1,
      formatVersion: 2,
      specification: "docs/spec-v0.2.md",
      generatedBy: "scripts/build-conformance.mjs",
      cases: written,
    },
    null,
    2,
  ) + "\n",
);

console.log(`${written.length} cases written to conformance/cases.json`);

/*
 * The same documents, carried in links (§1.1).
 *
 * Only the intact viewer-form cases: a link is made from a document a reader
 * has already verified, and the sender refuses to pack a damaged one. The
 * damaged cases for the carrier are made by damaging a link, which the Python
 * runner does itself.
 */
const { packInline } = await import("../dist/inline.js");
const host = {
  template: readFileSync(join(repo, "dist/template.html"), "utf8"),
  runtime: readFileSync(join(repo, "dist/dai-runtime.js"), "utf8"),
};
const links = [];
for (const entry of written) {
  if (entry.form !== "viewer" || entry.expect.parses === false || entry.expect.ok !== true) continue;
  const html = readFileSync(join(suite, entry.file), "utf8");
  const value = await packInline(parseContainer(html), host);
  links.push({
    name: entry.name,
    link: `https://opener.example/#a=${value}`,
    expect: { ok: true, signature: entry.expect.signature, shell: "elided" },
  });
}
writeFileSync(
  join(suite, "inline-links.json"),
  JSON.stringify({ suiteVersion: 1, generatedBy: "scripts/build-conformance.mjs", links }, null, 2) + "\n",
);
console.log(`${links.length} links written to conformance/inline-links.json`);

/*
 * The isolation probe.
 *
 * Not a case: §4 describes a host, and no file can carry a verdict about one.
 * This is a container that runs the checks itself, from inside, and reports
 * what got through — so a host implementation has something to be measured by
 * rather than a paragraph to agree with.
 *
 * Built without the engine for the same reason the cases are: it tests the
 * boundary, not SQLite, and half a megabyte of WebAssembly would buy nothing.
 */
const probe = await buildContainer(
  base({
    files: Object.fromEntries(
      ["index.html", "probe.js", "probe.css"].map((name) => [
        name,
        readFileSync(join(suite, "isolation", name)),
      ]),
    ),
    appName: "Isolation probe",
    documentUuid: "6ba7b810-9dad-11d1-80b4-00c04fd430c8",
  }),
);

writeFileSync(join(suite, "isolation-probe.dai.html"), probe.html);
console.log("isolation probe written to conformance/isolation-probe.dai.html");
